CREATE TABLE users(id INTEGER PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')), blocked INTEGER NOT NULL DEFAULT 0, avatar TEXT NOT NULL DEFAULT '', session_version INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE courses(id INTEGER PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', summary TEXT NOT NULL DEFAULT '', outcomes TEXT NOT NULL DEFAULT '', prerequisites TEXT NOT NULL DEFAULT '', category_id INTEGER REFERENCES categories(id), level TEXT NOT NULL DEFAULT 'Начальный' CHECK(level IN ('Начальный','Средний','Продвинутый')), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), cover TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE modules(id INTEGER PRIMARY KEY, course_id INTEGER NOT NULL REFERENCES courses(id), title TEXT NOT NULL, position INTEGER NOT NULL);
CREATE TABLE lessons(id INTEGER PRIMARY KEY, module_id INTEGER NOT NULL REFERENCES modules(id), title TEXT NOT NULL, content TEXT NOT NULL DEFAULT '', video TEXT NOT NULL DEFAULT '', minutes INTEGER NOT NULL DEFAULT 15 CHECK(minutes>0), position INTEGER NOT NULL, required INTEGER NOT NULL DEFAULT 1 CHECK(required=1));
CREATE TABLE quizzes(id INTEGER PRIMARY KEY, lesson_id INTEGER NOT NULL UNIQUE REFERENCES lessons(id), pass_score INTEGER NOT NULL CHECK(pass_score BETWEEN 1 AND 100));
CREATE TABLE questions(id INTEGER PRIMARY KEY, quiz_id INTEGER NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE, text TEXT NOT NULL, options TEXT NOT NULL, correct TEXT NOT NULL, explanation TEXT NOT NULL DEFAULT '');
CREATE TABLE enrollments(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), course_id INTEGER NOT NULL REFERENCES courses(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_activity TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_lesson INTEGER REFERENCES lessons(id), completed_at TEXT, UNIQUE(user_id,course_id));
CREATE TABLE progress(id INTEGER PRIMARY KEY, enrollment_id INTEGER NOT NULL REFERENCES enrollments(id), lesson_id INTEGER NOT NULL REFERENCES lessons(id), started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT, UNIQUE(enrollment_id,lesson_id));
CREATE TABLE attempts(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), quiz_id INTEGER NOT NULL REFERENCES quizzes(id), score INTEGER NOT NULL, passed INTEGER NOT NULL, answers TEXT NOT NULL, feedback TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE events(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), course_id INTEGER REFERENCES courses(id), text TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE favorites(user_id INTEGER NOT NULL REFERENCES users(id), course_id INTEGER NOT NULL REFERENCES courses(id), PRIMARY KEY(user_id,course_id));
CREATE TABLE notes(user_id INTEGER NOT NULL REFERENCES users(id), lesson_id INTEGER NOT NULL REFERENCES lessons(id), text TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,lesson_id));
CREATE TABLE reviews(user_id INTEGER NOT NULL REFERENCES users(id), course_id INTEGER NOT NULL REFERENCES courses(id), rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), text TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,course_id));
CREATE TABLE notifications(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), text TEXT NOT NULL, seen INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE certificates(id TEXT PRIMARY KEY, enrollment_id INTEGER NOT NULL UNIQUE REFERENCES enrollments(id), name TEXT NOT NULL, course TEXT NOT NULL, issued_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), action TEXT NOT NULL, object TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE materials(id INTEGER PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES users(id), lesson_id INTEGER REFERENCES lessons(id), name TEXT NOT NULL, path TEXT NOT NULL UNIQUE, kind TEXT NOT NULL CHECK(kind IN ('image','file')), public INTEGER NOT NULL DEFAULT 0);
CREATE TABLE login_limits(key TEXT PRIMARY KEY, count INTEGER NOT NULL DEFAULT 0, since INTEGER NOT NULL);
CREATE INDEX ix_events_user ON events(user_id,created_at);
CREATE INDEX ix_enrollments_course ON enrollments(course_id);
CREATE INDEX ix_progress_enrollment ON progress(enrollment_id);
